import { test, expect } from '@playwright/test';

test.describe('Table Column Sort Direction Indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display ascending arrow icon when column is sorted ascending', async ({ page }) => {
    // Click on a sortable column header
    const columnHeader = page.getByRole('columnheader', { name: /name/i });
    await columnHeader.click();

    // Verify ascending arrow icon is visible
    const ascendingArrow = columnHeader.locator('svg[data-testid="sort-ascending"]');
    await expect(ascendingArrow).toBeVisible();
  });

  test('should display descending arrow icon when column is sorted descending', async ({ page }) => {
    // Click on a sortable column header twice to toggle to descending
    const columnHeader = page.getByRole('columnheader', { name: /name/i });
    await columnHeader.click();
    await columnHeader.click();

    // Verify descending arrow icon is visible
    const descendingArrow = columnHeader.locator('svg[data-testid="sort-descending"]');
    await expect(descendingArrow).toBeVisible();
  });

  test('should remove arrow icon when column sort is cleared', async ({ page }) => {
    // Click on a sortable column header to sort
    const columnHeader = page.getByRole('columnheader', { name: /name/i });
    await columnHeader.click();

    // Verify arrow icon is visible
    let sortArrow = columnHeader.locator('svg[data-testid*="sort-"]');
    await expect(sortArrow).toBeVisible();

    // Click three times to clear the sort
    await columnHeader.click();
    await columnHeader.click();

    // Verify arrow icon is no longer visible
    sortArrow = columnHeader.locator('svg[data-testid*="sort-"]');
    await expect(sortArrow).not.toBeVisible();
  });

  test('should update arrow icon when switching sort between columns', async ({ page }) => {
    // Sort by first column
    const nameHeader = page.getByRole('columnheader', { name: /name/i });
    await nameHeader.click();

    // Verify arrow is on first column
    let nameArrow = nameHeader.locator('svg[data-testid*="sort-"]');
    await expect(nameArrow).toBeVisible();

    // Sort by second column
    const emailHeader = page.getByRole('columnheader', { name: /email/i });
    await emailHeader.click();

    // Verify arrow moved to second column
    const emailArrow = emailHeader.locator('svg[data-testid*="sort-"]');
    await expect(emailArrow).toBeVisible();

    // Verify arrow is no longer on first column
    nameArrow = nameHeader.locator('svg[data-testid*="sort-"]');
    await expect(nameArrow).not.toBeVisible();
  });
});
